#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# CHR HotSpot identity lab (answers Q2 in docs/research/hotspot-identity-lab.md,
# cases L1-L4). Run it as ./lab/chr/wizard.sh from anywhere in the repo.
#
# The library reads ENV_FILE lazily inside its functions, so reassigning it here
# (after the library definitions) points ask/write_env at the lab's own .env.

TOTAL_STAGES=12

LAB_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ENV_FILE="$LAB_DIR/.env"
REPO_ROOT="$(git -C "$LAB_DIR" rev-parse --show-toplevel)"
RUN_DIR="$REPO_ROOT/docs/research/results/$(date +%F)-chr-cookie-mac"

IMG=/var/lib/libvirt/images/chr-lab.qcow2
HS_GW=10.5.50.1
MAC_A=02:00:00:00:0a:01
MAC_A2=02:00:00:00:0a:02

# Values saved by earlier runs; ask() only offers them, it does not load them.
for _k in CHR_VERSION CHR_PASSWORD CHR_WAN_IP WAIT_SECS; do
  printf -v "$_k" '%s' "$(_existing "$_k" || true)"
done
WAIT_SECS="${WAIT_SECS:-60}"
CASE_L1="not run"; CASE_L2="not run"; CASE_L3="not run"; CASE_L4="not run"
CASE=""

# ── Helpers ───────────────────────────────────────────────────────────────

vsh() { virsh -c qemu:///system "$@"; }

# rest PATH [curl args...]: call the CHR REST API on its WAN address (ether1).
rest() {
  local path="$1"; shift
  curl -s --max-time 10 -u "admin:$CHR_PASSWORD" "$@" "http://$CHR_WAN_IP/rest$path"
}

# rest_version prints the RouterOS version; fails if REST is unreachable.
rest_version() {
  rest /system/resource | python3 -I -c 'import json,sys; print(json.load(sys.stdin)["version"])' 2>/dev/null
}

# hs1_state prints "<id> <disabled>" (e.g. "*1 false") for HotSpot hs1; empty if absent.
hs1_state() {
  rest /ip/hotspot | python3 -I -c '
import json, sys
for e in json.load(sys.stdin):
    if e.get("name") == "hs1":
        print(e[".id"], e.get("disabled", "false"))
' 2>/dev/null
}

# nsx NS cmd...: run a command inside a client namespace.
nsx() { local ns="$1"; shift; sudo ip netns exec "$ns" "$@"; }

# snap CASE LABEL: save active/host/cookie/user as JSON, then print a summary.
snap() {
  local case_id="$1" label="$2" dir="$RUN_DIR/$1" n
  mkdir -p "$dir"
  for n in active host cookie user; do
    rest "/ip/hotspot/$n" > "$dir/$label-$n.json" || true
  done
  printf '\n  %s[%s / %s]%s\n' "$BOLD" "$case_id" "$label" "$RESET"
  python3 -I - "$dir" "$label" <<'PY'
import json, os, sys

d, label = sys.argv[1:3]

def load(name):
    try:
        with open(os.path.join(d, f"{label}-{name}.json")) as f:
            return json.load(f)
    except Exception as e:
        return f"unreadable: {e}"

def show(title, data, keys):
    print(f"    {title}:")
    if not isinstance(data, list):
        print(f"      {data}")
        return
    if not data:
        print("      (none)")
    for e in data:
        print("      " + "  ".join(f"{k}={e.get(k, '-')}" for k in keys))

show("active", load("active"), ["user", "mac-address", "address", "uptime"])
show("host", load("host"), ["mac-address", "address"])
show("cookie", load("cookie"), ["user", "mac-address"])
show("user uptime", load("user"), ["name", "uptime", "limit-uptime"])
PY
}

# hc NS curl-args...: curl from inside NS with the case jar (JAR_NAME overrides
# "jar"). Sets HC_STATUS; saves the body to $HC_BODY when set; logs to transcript.
hc() {
  local ns="$1"; shift
  local jar="$RUN_DIR/$CASE/${JAR_NAME:-jar}" out
  mkdir -p "$RUN_DIR/$CASE"
  out=$(nsx "$ns" curl -s --max-time 15 -c "$jar" -b "$jar" -w '\n%{http_code}' "$@") || true
  HC_STATUS="${out##*$'\n'}"
  if [[ -n "${HC_BODY:-}" ]]; then printf '%s\n' "${out%$'\n'*}" > "$HC_BODY"; fi
  printf '%s curl[%s/%s] %s -> HTTP %s\n' "$(date +%T)" "$ns" "${JAR_NAME:-jar}" "$*" "$HC_STATUS" \
    >> "$RUN_DIR/$CASE/transcript.log"
}

login()  { hc "$1" -d "username=$2&password=$2&dst=&popup=true" "http://$HS_GW/login"; }
logout() { hc "$1" "http://$HS_GW/logout"; }
probe()  { hc "$1" "http://$HS_GW/login"; }

# set_mac NS IF MAC IP: change a client's MAC and address (IP without prefix).
set_mac() {
  local ns="$1" ifc="$2" mac="$3" ip="$4"
  nsx "$ns" ip link set "$ifc" down
  nsx "$ns" ip link set "$ifc" address "$mac"
  nsx "$ns" ip addr flush dev "$ifc"
  nsx "$ns" ip addr add "$ip/24" dev "$ifc"
  nsx "$ns" ip link set "$ifc" up
  nsx "$ns" ip route replace default via "$HS_GW"
}

# is_active MAC: success if /ip/hotspot/active has that mac-address.
is_active() {
  rest /ip/hotspot/active | python3 -I -c '
import json, sys
mac = sys.argv[1].lower()
sys.exit(0 if any(e.get("mac-address", "").lower() == mac for e in json.load(sys.stdin)) else 1)
' "$1" 2>/dev/null
}

# countdown SECS: visible wait.
countdown() {
  local i
  for ((i = $1; i > 0; i--)); do printf '\r  waiting %3ss ' "$i"; sleep 1; done
  printf '\r%*s\r' 30 ''
}

# case_begin CASE: remove active+cookie entries, reset hsA, delete the jars.
CLEANED=""
case_begin() {
  CASE="$1"
  if [[ -z "$CLEANED" ]]; then
    warn "Before each case the wizard deletes ALL /ip/hotspot/active and /cookie entries on the CHR and resets hsA to $MAC_A."
    confirm "Clean up the lab CHR like this?" || exit 1
    CLEANED=1
  fi
  mkdir -p "$RUN_DIR/$CASE"
  local kind id
  for kind in active cookie; do
    # RouterOS ids look like "*1"; read them line by line so the shell never globs them.
    while IFS= read -r id; do
      [[ -n "$id" ]] && rest "/ip/hotspot/$kind/$id" -X DELETE >/dev/null
    done < <(rest "/ip/hotspot/$kind" | python3 -I -c 'import json,sys; [print(e[".id"]) for e in json.load(sys.stdin)]')
  done
  set_mac hsA vA "$MAC_A" 10.5.50.201
  rm -f "$RUN_DIR/$CASE/jar" "$RUN_DIR/$CASE/jarB"
}

# mac_case VAR LOGOUT CHANGE LATER (each 0/1): shared flow for L1-L3. Stores
# "auto-login" or "login page" in VAR, judged on whether hsA's MAC is active.
mac_case() {
  local var="$1" do_logout="$2" change="$3" later="$4" mac="$MAC_A"
  snap "$CASE" 0-baseline
  login hsA t-cookie; note "login -> HTTP $HC_STATUS"
  say "Letting the session consume time for ${WAIT_SECS}s..."
  countdown "$WAIT_SECS"
  snap "$CASE" 1-after-login
  if ! is_active "$mac"; then
    printf -v "$var" '%s' "login failed"
    printf '\n  %sResult:%s %s\n\n' "$BOLD" "$RESET" "${!var}"
    note "Saved under $RUN_DIR/$CASE"
    pause "Press Enter for the next stage"
    return
  fi
  if [[ "$do_logout" == 1 ]]; then
    logout hsA; note "logout -> HTTP $HC_STATUS"
    snap "$CASE" 2-after-logout
  fi
  if [[ "$change" == 1 ]]; then
    mac="$MAC_A2"
    set_mac hsA vA "$mac" 10.5.50.211
    note "hsA is now $mac / 10.5.50.211"
  fi
  probe hsA; note "probe -> HTTP $HC_STATUS"
  sleep 2
  snap "$CASE" 3-after-change
  if [[ "$later" == 1 ]]; then
    say "Waiting ${WAIT_SECS}s to see what happens to the old entry..."
    countdown "$WAIT_SECS"
    snap "$CASE" 4-later
  fi
  if is_active "$mac"; then printf -v "$var" '%s' "auto-login"; else printf -v "$var" '%s' "login page"; fi
  printf '\n  %sResult:%s %s\n\n' "$BOLD" "$RESET" "${!var}"
  note "Saved under $RUN_DIR/$CASE"
  pause "Press Enter for the next stage"
}

# ── Wizard ────────────────────────────────────────────────────────────────

banner "CHR HotSpot identity lab"

stage "Preflight"
say "Checking the host can run the lab."
missing=()
for c in virsh virt-install qemu-img curl unzip ip sudo python3; do
  command -v "$c" >/dev/null 2>&1 || missing+=("command: $c")
done
[[ -e /dev/kvm ]] || missing+=("/dev/kvm (KVM not available)")
if command -v virsh >/dev/null 2>&1 && ! vsh list >/dev/null 2>&1; then
  missing+=("virsh -c qemu:///system list fails (libvirtd running? user in libvirt group?)")
fi
if (( ${#missing[@]} )); then
  for m in "${missing[@]}"; do warn "missing: $m"; done
  exit 1
fi
say "All prerequisites present."
pause

stage "Download the CHR image"
vsh pool-refresh default >/dev/null 2>&1 || true
if vsh vol-info --pool default chr-lab.qcow2 >/dev/null 2>&1; then
  note "$IMG already exists: skipping download."
else
  open_url "https://mikrotik.com/download"
  step "Find the stable 'Cloud Hosted Router' version (the Chr.img column, e.g. 7.x.y)."
  ask CHR_VERSION "CHR version:"
  [[ -n "$CHR_VERSION" ]] || { warn "no version given"; exit 1; }
  write_env CHR_VERSION "$CHR_VERSION"
  url="https://download.mikrotik.com/routeros/${CHR_VERSION}/chr-${CHR_VERSION}.img.zip"
  confirm "Download $url, then sudo-convert it to $IMG?" || { warn "aborted"; exit 1; }
  tmp=$(mktemp -d)
  if ! curl -fL --progress-bar -o "$tmp/chr.zip" "$url"; then
    warn "download failed (a 404 means the file name differs): check the download page for the exact file name."
    rm -rf "$tmp"; exit 1
  fi
  unzip -q -d "$tmp" "$tmp/chr.zip"
  if [[ ! -f "$tmp/chr-${CHR_VERSION}.img" ]]; then
    warn "chr-${CHR_VERSION}.img not found in the zip; contents:"; ls "$tmp"
    rm -rf "$tmp"; exit 1
  fi
  sudo qemu-img convert -f raw -O qcow2 "$tmp/chr-${CHR_VERSION}.img" "$IMG"
  rm -rf "$tmp"
  vsh pool-refresh default >/dev/null 2>&1 || true
  say "Created $IMG"
fi
pause

stage "Network hotspot-lan"
say "An isolated bridge (virbr-hs) with no IP and no DHCP: RouterOS is the only DHCP server."
note "The existing networks 'default' and 'pisonet' are not touched."
net_exists=0; net_active=0; net_auto=0
if vsh net-info hotspot-lan >/dev/null 2>&1; then
  net_exists=1
  net_info=$(vsh net-info hotspot-lan)
  if grep -Eq '^Active:[[:space:]]+yes' <<<"$net_info"; then net_active=1; fi
  if grep -Eq '^Autostart:[[:space:]]+yes' <<<"$net_info"; then net_auto=1; fi
fi
if (( net_exists && net_active && net_auto )); then
  note "hotspot-lan already defined, active and autostarted."
else
  confirm "Define/start/autostart libvirt network hotspot-lan?" || { warn "aborted"; exit 1; }
  if (( ! net_exists )); then
    xml=$(mktemp)
    cat > "$xml" <<'XML'
<network>
  <name>hotspot-lan</name>
  <bridge name='virbr-hs' stp='off'/>
</network>
XML
    vsh net-define "$xml"
    rm -f "$xml"
  fi
  if (( ! net_active )); then vsh net-start hotspot-lan; fi
  vsh net-autostart hotspot-lan
fi
printf '\n'
vsh net-dumpxml hotspot-lan
printf '\n'
pause

stage "VM chr-lab"
if ! vsh vol-info --pool default chr-lab.qcow2 >/dev/null 2>&1; then
  warn "$IMG is missing: re-run the wizard and complete the download stage."
  exit 1
fi
if vsh dominfo chr-lab >/dev/null 2>&1; then
  note "VM chr-lab already exists: not redefining it."
else
  say "NIC order matters: the first NIC is ether1 (WAN, default NAT), the second is ether2 (hotspot-lan)."
  confirm "Create VM chr-lab with virt-install?" || { warn "aborted"; exit 1; }
  virt-install --connect qemu:///system --name chr-lab --memory 256 --vcpus 1 --import \
    --disk "$IMG,bus=virtio" \
    --network network=default,model=virtio \
    --network network=hotspot-lan,model=virtio \
    --osinfo detect=on,require=off --graphics none --noautoconsole
fi
if [[ "$(vsh domstate chr-lab)" == "shut off" ]]; then
  if confirm "chr-lab is shut off. Start it?"; then vsh start chr-lab; fi
fi
vsh domstate chr-lab
pause

stage "First login and REST check"
if [[ -n "$CHR_PASSWORD" && -n "$CHR_WAN_IP" ]] && rest_version >/dev/null; then
  note "REST already works on $CHR_WAN_IP (RouterOS $(rest_version)): skipping."
else
  step "Open a second terminal and run: virsh -c qemu:///system console chr-lab   (exit with Ctrl-])"
  step "Log in as 'admin' with an empty password, accept the licence prompt, set a new password."
  ask_secret CHR_PASSWORD "New admin password (kept only in lab/chr/.env, gitignored):"
  write_env CHR_PASSWORD "$CHR_PASSWORD"
  step "In the console run: /ip address print    (ether1 has a 192.168.122.x address from the default NAT)"
  note "Hint from libvirt: $(vsh domifaddr chr-lab --source lease 2>/dev/null | grep -Eo '192\.168\.122\.[0-9]+' | head -n1 || true)"
  ask CHR_WAN_IP "ether1 address (no /24):"
  write_env CHR_WAN_IP "$CHR_WAN_IP"
  note "Plain HTTP REST is acceptable only because this lab is isolated. RouterOS 7.9+ serves REST on the www service."
  while true; do
    if ver=$(rest_version); then say "REST OK: RouterOS $ver"; break; fi
    warn "REST failed. In the console run: /ip service enable www    (then check /ip service print)"
    confirm "Try again?" || exit 1
  done
fi
pause

stage "HotSpot config"
hs1=$(hs1_state)
if [[ "$hs1" == *" true" ]]; then
  # RouterOS 7.x can create the server disabled, so nothing intercepts ether2.
  warn "HotSpot hs1 exists but is disabled: clients would hit the plain www service."
  confirm "Enable hs1 over REST?" || { warn "aborted"; exit 1; }
  rest "/ip/hotspot/${hs1% *}" -X PATCH -H 'content-type: application/json' -d '{"disabled":"false"}' >/dev/null
  [[ "$(hs1_state)" == *" false" ]] || { warn "hs1 is still disabled"; exit 1; }
  say "hs1 enabled."
elif [[ "$hs1" == *" false" ]]; then
  note "HotSpot hs1 already exists and is enabled on the CHR: skipping."
else
  cat > "$LAB_DIR/hotspot.rsc" <<'RSC'
# Check each command against the installed RouterOS version's HotSpot docs
# (https://help.mikrotik.com/docs/spaces/ROS/pages/56459266/HotSpot+-+Captive+portal).
/ip address add address=10.5.50.1/24 interface=ether2
/ip pool add name=hs-pool ranges=10.5.50.10-10.5.50.200
/ip dhcp-server add name=hs-dhcp interface=ether2 address-pool=hs-pool lease-time=10m
/ip dhcp-server network add address=10.5.50.0/24 gateway=10.5.50.1 dns-server=10.5.50.1
/ip firewall nat add chain=srcnat out-interface=ether1 action=masquerade
/ip hotspot profile add name=hs-prof hotspot-address=10.5.50.1 login-by=cookie,http-pap http-cookie-lifetime=1d
/ip hotspot user profile add name=one-session shared-users=1
/ip hotspot add name=hs1 interface=ether2 address-pool=hs-pool profile=hs-prof disabled=no
/ip hotspot user add name=t-cookie password=t-cookie limit-uptime=1h
/ip hotspot user add name=t-takeover password=t-takeover profile=one-session limit-uptime=1h
RSC
  say "Wrote $LAB_DIR/hotspot.rsc. Paste these into the CHR console:"
  printf '\n'
  grep -v '^#' "$LAB_DIR/hotspot.rsc" | sed 's/^/    /'
  printf '\n'
  pause "Press Enter once pasted (any error lines mean the syntax differs on your version)"
  until [[ "$(hs1_state)" == *" false" ]]; do
    warn "GET /rest/ip/hotspot does not list hs1 as enabled yet (missing, or disabled=true)."
    confirm "Check again?" || exit 1
  done
  say "hs1 is listed and enabled."
fi
pause

stage "Client namespaces"
say "hsA and hsB are veth-attached clients on virbr-hs, with static IPs (the host has no DHCP client)."
# mk_ns NS LETTER MAC IP/PREFIX
mk_ns() {
  local ns="$1" l="$2" mac="$3" ip="$4"
  sudo ip link del "v$l-br" 2>/dev/null || true   # stale half-built veth from an aborted run
  sudo ip netns add "$ns"
  sudo ip link add "v$l-br" type veth peer name "v$l"
  sudo ip link set "v$l-br" master virbr-hs
  sudo ip link set "v$l-br" up
  sudo ip link set "v$l" netns "$ns"
  nsx "$ns" ip link set "v$l" address "$mac"
  nsx "$ns" ip addr add "$ip" dev "v$l"
  nsx "$ns" ip link set lo up
  nsx "$ns" ip link set "v$l" up
  nsx "$ns" ip route add default via "$HS_GW"
}
ns_missing=()
for ns in hsA hsB; do
  if [[ " $(ip netns list | awk '{print $1}' | tr '\n' ' ')" == *" $ns "* ]]; then
    note "namespace $ns exists: skipping."
  else
    ns_missing+=("$ns")
  fi
done
if (( ${#ns_missing[@]} )); then
  confirm "Create namespace(s) ${ns_missing[*]} with sudo ip commands?" || { warn "aborted"; exit 1; }
  for ns in "${ns_missing[@]}"; do
    case "$ns" in
      hsA) mk_ns hsA A 02:00:00:00:0a:01 10.5.50.201/24 ;;
      hsB) mk_ns hsB B 02:00:00:00:0b:01 10.5.50.202/24 ;;
    esac
  done
fi
sleep 3
code=$(nsx hsA curl -s -m 10 -o /dev/null -w '%{http_code}' "http://$HS_GW/login" || true)
if [[ "$code" == 200 ]]; then
  say "hsA -> http://$HS_GW/login: HTTP 200"
else
  warn "hsA -> http://$HS_GW/login returned HTTP ${code:-none}, expected 200 (is hs1 enabled?)"
  confirm "Continue anyway?" || exit 1
fi
note "Teardown: sudo ip netns del hsA; sudo ip netns del hsB; sudo ip link del vA-br; sudo ip link del vB-br"
pause

stage "Case L1: MAC change after logout"
say "User t-cookie in hsA: login, wait, logout, change MAC, probe /login."
ask WAIT_SECS "Seconds to wait for uptime to accrue:"
[[ "$WAIT_SECS" =~ ^[0-9]+$ ]] || WAIT_SECS=60
write_env WAIT_SECS "$WAIT_SECS"
case_begin L1
mac_case CASE_L1 1 1 0

stage "Case L2: MAC change while active"
say "User t-cookie in hsA: login, wait, change MAC WITHOUT logout, probe, then wait again."
case_begin L2
mac_case CASE_L2 0 1 1

stage "Case L3: control (no MAC change)"
say "User t-cookie in hsA: login, wait, logout, keep the MAC, probe /login."
case_begin L3
mac_case CASE_L3 1 0 0

stage "Case L4: takeover"
say "User t-takeover (shared-users=1): login from hsA, then from hsB with its own jar."
case_begin L4
snap L4 0-baseline
login hsA t-takeover; note "A login -> HTTP $HC_STATUS"
sleep 2
snap L4 1-after-A
if ! is_active "$MAC_A"; then
  CASE_L4="login failed"
else
  JAR_NAME=jarB HC_BODY="$RUN_DIR/L4/B-login-response.html" login hsB t-takeover
  note "B login -> HTTP $HC_STATUS (body saved to L4/B-login-response.html)"
  sleep 2
  snap L4 2-after-B
  a=0; b=0
  is_active "$MAC_A" && a=1
  is_active 02:00:00:00:0b:01 && b=1
  if   (( a && b )); then CASE_L4="both active"
  elif (( b ));      then CASE_L4="replaced A"
  elif (( a ));      then CASE_L4="rejected B"
  else                    CASE_L4="neither active"
  fi
fi
printf '\n  %sResult:%s %s\n\n' "$BOLD" "$RESET" "$CASE_L4"
pause "Press Enter for the last stage"

stage "Results skeleton"
mkdir -p "$RUN_DIR"
ros_version=$(rest_version || echo unknown)
cat > "$RUN_DIR/results.md" <<MD
# CHR cookie / MAC lab results ($(date +%F))

- RouterOS version: $ros_version
- CHR_VERSION (image): ${CHR_VERSION:-unknown}
- Date: $(date +%F)
- WAIT_SECS: $WAIT_SECS

| Case | Auto-login after change? | Cookie entry MAC (before → after) | user uptime/limit before → after | Old active/host entry fate |
|---|---|---|---|---|
| L1 MAC change after logout | $CASE_L1 | TODO (see JSON) | TODO (see JSON) | TODO (see JSON) |
| L2 MAC change while active | $CASE_L2 | TODO (see JSON) | TODO (see JSON) | TODO (see JSON) |
| L3 control | $CASE_L3 | TODO (see JSON) | TODO (see JSON) | TODO (see JSON) |
| L4 takeover | $CASE_L4 | TODO (see JSON) | TODO (see JSON) | TODO (see JSON) |

Label each finding E (observed), C (characterization) or D (desired property), and link this file from \`docs/research/hotspot-identity-lab.md\` Q2.
Raw snapshots and curl transcripts are in the per-case folders next to this file.
MD
say "Wrote $RUN_DIR/results.md"
note "Teardown hint: see lab/chr/README.md"
# ──────────────────────────────────────────────────────────────────────────

finish
printf '  RUN_DIR: %s\n\n' "$RUN_DIR"
